public static long countGoodIntegers(long N) {
    long count = 0;
    for (long i = 1; i <= N; i++) {
        long sumOfDigits = 0;
        long number = i;
        while (number > 0) {
            sumOfDigits += number % 10;
            number /= 10;
        }
        if (i % sumOfDigits == 0) {
            count++;
        }
    }
    return count;
}

public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    InputReader sc = new InputReader(System.in);
    long n = sc.nextLong();
    long result = countGoodIntegers(n);
    System.out.println(result);
}
